//! Turns a request in natural language (typed after `#`) into a shell command,
//! like Warp's AI command search. The command is generated by the user's own
//! agent CLI, Claude Code (`claude -p`) or Codex (`codex exec`), so it uses
//! their subscription and needs no API key in Solo.
//!
//! SOLO: requests start with an explicit `#`; Solo doesn't guess whether the
//! input is a command or a request the way Warp's Agent Mode does. Solo's
//! terminals mostly run agents, and sending a command (or what was meant for
//! an agent) to an AI by mistake costs more than typing `#`.
//!
//! Generating never runs anything:
//! - Claude Code runs with no tools (`--tools ""`, and `--disallowedTools "*"`
//!   for MCP tools too) and denies anything that would need permission;
//! - Codex runs in a read-only sandbox with its shell tool turned off;
//! - both run in an empty directory of Solo's, so the project's hooks, MCP
//!   servers and instruction files don't load (which also starts them
//!   faster), and Claude Code's hooks are turned off;
//! - the answer only fills the input, for the user to review and run.

use std::ffi::OsString;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use anyhow::{Context as _, Result, anyhow};
use terminal::terminal_settings::AiCommandAgent;

use super::completion::ShellFlavor;
use super::powershell::hide_window;

const TIMEOUT: Duration = Duration::from_secs(90);
/// How much of a command's output goes into the prompt, from its end.
pub const MAX_OUTPUT_CHARS: usize = 4000;
const MAX_COMMAND_CHARS: usize = 1000;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AgentKind {
    ClaudeCode,
    Codex,
}

impl AgentKind {
    pub fn name(self) -> &'static str {
        match self {
            Self::ClaudeCode => "Claude Code",
            Self::Codex => "Codex",
        }
    }

    fn executable_names(self) -> &'static [&'static str] {
        match (self, cfg!(windows)) {
            (Self::ClaudeCode, true) => &["claude.exe", "claude.cmd"],
            (Self::ClaudeCode, false) => &["claude"],
            (Self::Codex, true) => &["codex.exe", "codex.cmd"],
            (Self::Codex, false) => &["codex"],
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Agent {
    pub kind: AgentKind,
    pub program: PathBuf,
}

/// A command block sent along as context.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ContextBlock {
    pub command: String,
    pub output: String,
    pub exit_code: Option<i32>,
}

#[derive(Clone, Debug, Default)]
pub struct Request {
    pub request: String,
    pub shell: Option<String>,
    pub cwd: Option<PathBuf>,
    pub context: Vec<ContextBlock>,
}

#[derive(Clone, Debug, Default)]
pub struct Options {
    pub agent: AiCommandAgent,
    /// Claude Code's `--model`; empty uses its default.
    pub claude_model: String,
    /// Codex's `--model`; empty uses its default.
    pub codex_model: String,
}

/// Returned (inside the error) when the user cancelled generating.
#[derive(Debug)]
pub struct Cancelled;

impl std::fmt::Display for Cancelled {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("cancelled")
    }
}

impl std::error::Error for Cancelled {}

/// Generates a command for `request` with the agent the settings pick.
/// Returns early with [`Cancelled`] once `cancel` is set.
pub fn generate_command(
    request: &Request,
    options: &Options,
    cancel: &AtomicBool,
) -> Result<String> {
    let agent = choose_agent(options.agent, find_program)?;
    generate_with(&agent, request, options, cancel)
}

/// The agent to generate with: the one asked for, or with "auto" Claude Code
/// if it's installed, else Codex.
pub fn choose_agent(
    preference: AiCommandAgent,
    find: impl Fn(AgentKind) -> Option<PathBuf>,
) -> Result<Agent> {
    let candidates: &[AgentKind] = match preference {
        AiCommandAgent::Auto => &[AgentKind::ClaudeCode, AgentKind::Codex],
        AiCommandAgent::ClaudeCode => &[AgentKind::ClaudeCode],
        AiCommandAgent::Codex => &[AgentKind::Codex],
    };
    candidates
        .iter()
        .find_map(|kind| {
            find(*kind).map(|program| Agent {
                kind: *kind,
                program,
            })
        })
        .ok_or_else(|| anyhow!(not_installed_message(preference)))
}

fn not_installed_message(preference: AiCommandAgent) -> String {
    let claude = if cfg!(windows) {
        "irm https://claude.ai/install.ps1 | iex"
    } else {
        "curl -fsSL https://claude.ai/install.sh | bash"
    };
    let codex = "npm install -g @openai/codex";
    let chinese = util::i18n::is_chinese();
    match (preference, chinese) {
        (AiCommandAgent::Auto, true) => format!(
            "没找到 Claude Code 或 Codex，无法生成命令。装一个即可：Claude Code 用 `{claude}` 安装，Codex 用 `{codex}` 安装"
        ),
        (AiCommandAgent::Auto, false) => format!(
            "Neither Claude Code nor Codex is installed, so commands can't be generated. \
             Install one: Claude Code with `{claude}`, Codex with `{codex}`"
        ),
        (AiCommandAgent::ClaudeCode, true) => format!(
            "没找到 Claude Code（PATH 里没有 claude）。用 `{claude}` 安装，或把设置 terminal.ai_command_agent 改为 \"auto\""
        ),
        (AiCommandAgent::ClaudeCode, false) => format!(
            "Claude Code isn't installed (no `claude` on PATH). Install it with `{claude}`, \
             or set terminal.ai_command_agent to \"auto\""
        ),
        (AiCommandAgent::Codex, true) => format!(
            "没找到 Codex（PATH 里没有 codex）。用 `{codex}` 安装，或把设置 terminal.ai_command_agent 改为 \"auto\""
        ),
        (AiCommandAgent::Codex, false) => format!(
            "Codex isn't installed (no `codex` on PATH). Install it with `{codex}`, \
             or set terminal.ai_command_agent to \"auto\""
        ),
    }
}

/// The agent's executable: on `PATH`, or where Claude Code's native
/// installer puts it.
pub fn find_program(kind: AgentKind) -> Option<PathBuf> {
    let path = std::env::var_os("PATH").unwrap_or_default();
    std::env::split_paths(&path)
        .chain(
            std::env::var_os(if cfg!(windows) { "USERPROFILE" } else { "HOME" })
                .map(|home| PathBuf::from(home).join(".local").join("bin")),
        )
        .flat_map(|dir| {
            kind.executable_names()
                .iter()
                .map(move |name| dir.join(name))
        })
        .find(|candidate| candidate.is_file())
}

/// Generates with a given agent.
pub fn generate_with(
    agent: &Agent,
    request: &Request,
    options: &Options,
    cancel: &AtomicBool,
) -> Result<String> {
    static RUNS: AtomicUsize = AtomicUsize::new(0);
    let work_dir = work_dir()?;
    let answer_file = (agent.kind == AgentKind::Codex).then(|| {
        work_dir.join(format!(
            "answer-{}-{}.txt",
            std::process::id(),
            RUNS.fetch_add(1, Ordering::Relaxed)
        ))
    });
    let model = match agent.kind {
        AgentKind::ClaudeCode => &options.claude_model,
        AgentKind::Codex => &options.codex_model,
    };
    let mut command = Command::new(&agent.program);
    command
        .args(agent_args(
            agent.kind,
            model,
            &work_dir.join("claude-settings.json"),
            answer_file.as_deref(),
        ))
        .current_dir(&work_dir);
    let output = run(command, &prompt(request), TIMEOUT, cancel);
    let answer = answer_file.as_ref().and_then(|file| {
        let answer = std::fs::read_to_string(file).ok();
        std::fs::remove_file(file).ok();
        answer.filter(|answer| !answer.trim().is_empty())
    });
    let output = output.map_err(|error| {
        if error.is::<Cancelled>() {
            error
        } else {
            error.context(if util::i18n::is_chinese() {
                format!("{} 生成命令失败", agent.kind.name())
            } else {
                format!("{} couldn't generate the command", agent.kind.name())
            })
        }
    })?;
    let command = clean_answer(answer.as_deref().unwrap_or(&output));
    if command.is_empty() {
        return Err(anyhow!(if util::i18n::is_chinese() {
            format!("{} 没有返回命令", agent.kind.name())
        } else {
            format!("{} returned no command", agent.kind.name())
        }));
    }
    Ok(command)
}

/// An empty directory the agent runs in, so nothing from the project (hooks,
/// MCP servers, CLAUDE.md, AGENTS.md) loads.
fn work_dir() -> Result<PathBuf> {
    let dir = std::env::temp_dir().join("solo-ai-command");
    std::fs::create_dir_all(&dir).context("creating the directory to generate commands in")?;
    let settings = dir.join("claude-settings.json");
    if std::fs::read_to_string(&settings).ok().as_deref() != Some(CLAUDE_SETTINGS) {
        std::fs::write(&settings, CLAUDE_SETTINGS).context("writing Claude Code's settings")?;
    }
    Ok(dir)
}

/// Settings added to the user's own for the run: no hooks.
const CLAUDE_SETTINGS: &str = r#"{"disableAllHooks": true}"#;

/// The agent's arguments. The prompt goes to its stdin, which survives any
/// quoting (`claude.cmd` and `codex.cmd` run through cmd.exe).
pub fn agent_args(
    kind: AgentKind,
    model: &str,
    claude_settings: &Path,
    answer_file: Option<&Path>,
) -> Vec<OsString> {
    let mut args: Vec<OsString> = Vec::new();
    match kind {
        AgentKind::ClaudeCode => {
            // Per Claude Code's CLI reference: `--tools ""` removes every
            // built-in tool, `--disallowedTools "*"` every tool including
            // MCP ones, and `dontAsk` denies whatever would need permission.
            for arg in [
                "-p",
                "--output-format",
                "text",
                "--tools",
                "",
                "--disallowedTools",
                "*",
                "--permission-mode",
                "dontAsk",
                "--strict-mcp-config",
                "--no-session-persistence",
                "--settings",
            ] {
                args.push(arg.into());
            }
            args.push(claude_settings.as_os_str().to_owned());
        }
        AgentKind::Codex => {
            // Per Codex's CLI reference: a read-only sandbox, no shell tool,
            // and nothing saved; `-` reads the prompt from stdin.
            for arg in [
                "exec",
                "--sandbox",
                "read-only",
                "-c",
                "features.shell_tool=false",
                "--skip-git-repo-check",
                "--ephemeral",
                "--color",
                "never",
            ] {
                args.push(arg.into());
            }
            if let Some(answer_file) = answer_file {
                args.push("--output-last-message".into());
                args.push(answer_file.as_os_str().to_owned());
            }
        }
    }
    let model = model.trim();
    if !model.is_empty() {
        args.push("--model".into());
        args.push(model.into());
    }
    if kind == AgentKind::Codex {
        args.push("-".into());
    }
    args
}

pub fn prompt(request: &Request) -> String {
    let shell_name = match ShellFlavor::from_shell(request.shell.as_deref()) {
        ShellFlavor::PowerShell => "PowerShell",
        ShellFlavor::Posix => "bash",
    };
    let os = if cfg!(windows) {
        "Windows"
    } else if cfg!(target_os = "macos") {
        "macOS"
    } else {
        "Linux"
    };
    let cwd = request
        .cwd
        .as_ref()
        .map(|cwd| format!(" It will run in {}.", cwd.display()))
        .unwrap_or_default();
    let mut prompt = format!(
        "Write a {shell_name} command for {os} that does what the request below asks.{cwd} \
         Reply with only the command, on as few lines as possible, with no explanation, \
         no markdown and no code fences. You have no tools: don't try to run or check \
         anything.\n\n"
    );
    if !request.context.is_empty() {
        prompt.push_str(
            "Recent commands in this terminal, with the end of their output. When the \
             request mentions an error or \"that\", it means these.\n<terminal>\n",
        );
        for block in &request.context {
            prompt.push_str("$ ");
            prompt.push_str(&head_chars(block.command.trim(), MAX_COMMAND_CHARS));
            prompt.push('\n');
            let output = tail_chars(block.output.trim_end(), MAX_OUTPUT_CHARS);
            if !output.is_empty() {
                prompt.push_str(&output);
                prompt.push('\n');
            }
            if let Some(code) = block.exit_code {
                prompt.push_str(&format!("(exit code {code})\n"));
            }
        }
        prompt.push_str("</terminal>\n\n");
    }
    prompt.push_str("Request: ");
    prompt.push_str(&request.request);
    prompt
}

/// The last `max` characters of `text`, marked when cut.
pub fn tail_chars(text: &str, max: usize) -> String {
    let count = text.chars().count();
    if count <= max {
        return text.to_string();
    }
    let skip = count - max;
    let start = text
        .char_indices()
        .nth(skip)
        .map_or(text.len(), |(ix, _)| ix);
    format!("[...]\n{}", &text[start..])
}

fn head_chars(text: &str, max: usize) -> String {
    match text.char_indices().nth(max) {
        Some((ix, _)) => format!("{} [...]", &text[..ix]),
        None => text.to_string(),
    }
}

/// Runs `command` with `input` on its stdin and returns its stdout. Stops it
/// when `cancel` is set or after `timeout`.
#[allow(
    clippy::disallowed_methods,
    reason = "generating runs on a background thread"
)]
fn run(
    mut command: Command,
    input: &str,
    timeout: Duration,
    cancel: &AtomicBool,
) -> Result<String> {
    command
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    hide_window(&mut command);
    let mut child = command.spawn().context(if util::i18n::is_chinese() {
        "无法启动"
    } else {
        "couldn't start it"
    })?;
    let stdin = child.stdin.take();
    let input = input.to_string();
    std::thread::spawn(move || {
        if let Some(mut stdin) = stdin {
            stdin.write_all(input.as_bytes()).ok();
        }
        // Dropping stdin ends the prompt.
    });
    fn read_all(
        pipe: Option<impl std::io::Read + Send + 'static>,
    ) -> std::thread::JoinHandle<String> {
        std::thread::spawn(move || {
            let mut output = Vec::new();
            if let Some(mut pipe) = pipe {
                pipe.read_to_end(&mut output).ok();
            }
            String::from_utf8_lossy(&output).into_owned()
        })
    }
    let stdout = read_all(child.stdout.take());
    let stderr = read_all(child.stderr.take());
    let deadline = Instant::now() + timeout;
    let status = loop {
        if cancel.load(Ordering::Relaxed) {
            kill_tree(&mut child);
            return Err(anyhow!(Cancelled));
        }
        match child.try_wait()? {
            Some(status) => break status,
            None if Instant::now() >= deadline => {
                kill_tree(&mut child);
                return Err(anyhow!(if util::i18n::is_chinese() {
                    format!("{} 秒内没有回答", timeout.as_secs())
                } else {
                    format!("no answer within {}s", timeout.as_secs())
                }));
            }
            None => std::thread::sleep(Duration::from_millis(20)),
        }
    };
    let stdout = stdout.join().unwrap_or_default();
    let stderr = stderr.join().unwrap_or_default();
    if !status.success() {
        // Claude Code reports failures such as a missing login on stdout.
        let detail = [stderr.trim(), stdout.trim()]
            .into_iter()
            .find(|text| !text.is_empty())
            .map(|text| tail_chars(text, 300))
            .unwrap_or_else(|| status.to_string());
        return Err(anyhow!(detail));
    }
    Ok(stdout)
}

/// Stops the agent and what it started (`claude.cmd` runs node under cmd.exe).
#[allow(
    clippy::disallowed_methods,
    reason = "generating runs on a background thread"
)]
fn kill_tree(child: &mut Child) {
    #[cfg(windows)]
    {
        let mut taskkill = Command::new("taskkill");
        taskkill
            .args(["/T", "/F", "/PID", &child.id().to_string()])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        hide_window(&mut taskkill);
        taskkill.status().ok();
    }
    child.kill().ok();
    child.wait().ok();
}

/// Strips code fences, a leading prompt sign and surrounding blank lines.
pub fn clean_answer(answer: &str) -> String {
    let lines: Vec<&str> = answer
        .lines()
        .filter(|line| !line.trim_start().starts_with("```"))
        .collect();
    let text = lines.join("\n");
    let text = text.trim();
    let text = text
        .strip_prefix("$ ")
        .or_else(|| text.strip_prefix("PS> "))
        .unwrap_or(text);
    text.trim_matches('`').trim().to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_clean_answer() {
        assert_eq!(
            clean_answer("```powershell\nGet-ChildItem\n```\n"),
            "Get-ChildItem"
        );
        assert_eq!(clean_answer("  `ls -la`  "), "ls -la");
        assert_eq!(clean_answer("$ du -sh *\n"), "du -sh *");
        assert_eq!(
            clean_answer("Get-ChildItem |\n  Sort-Object Length"),
            "Get-ChildItem |\n  Sort-Object Length"
        );
    }

    #[test]
    fn test_prompt_mentions_shell_and_request() {
        let prompt = prompt(&Request {
            request: "list big files".into(),
            shell: Some(r"C:\x\pwsh.exe".into()),
            ..Default::default()
        });
        assert!(prompt.contains("PowerShell"));
        assert!(!prompt.contains("<terminal>"));
        assert!(prompt.ends_with("Request: list big files"));
    }

    #[test]
    fn test_prompt_includes_failed_command_and_truncated_output() {
        let long_output = format!("{}\nerror: the real error", "noise line\n".repeat(1000));
        let prompt = prompt(&Request {
            request: "fix that error".into(),
            shell: Some("bash".into()),
            cwd: None,
            context: vec![ContextBlock {
                command: "cargo build".into(),
                output: long_output.clone(),
                exit_code: Some(101),
            }],
        });
        assert!(prompt.contains("$ cargo build\n"));
        assert!(prompt.contains("error: the real error"));
        assert!(prompt.contains("(exit code 101)"));
        // Only the end of the output, marked as cut.
        assert!(prompt.contains("[...]\n"));
        assert!(long_output.len() > MAX_OUTPUT_CHARS * 2);
        assert!(prompt.len() < MAX_OUTPUT_CHARS + 1000);
        assert!(prompt.ends_with("Request: fix that error"));
    }

    #[test]
    fn test_tail_chars_keeps_whole_characters() {
        assert_eq!(tail_chars("abc", 5), "abc");
        assert_eq!(tail_chars("一二三四", 2), "[...]\n三四");
    }

    #[test]
    fn test_claude_runs_without_tools() {
        let args: Vec<String> = agent_args(
            AgentKind::ClaudeCode,
            "haiku",
            Path::new("settings.json"),
            None,
        )
        .into_iter()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect();
        let value_of = |flag: &str| {
            args.iter()
                .position(|arg| arg == flag)
                .and_then(|ix| args.get(ix + 1))
                .map(String::as_str)
        };
        assert_eq!(value_of("--tools"), Some(""));
        assert_eq!(value_of("--disallowedTools"), Some("*"));
        assert_eq!(value_of("--permission-mode"), Some("dontAsk"));
        assert_eq!(value_of("--model"), Some("haiku"));
        assert_eq!(value_of("--settings"), Some("settings.json"));
        assert!(args.contains(&"--strict-mcp-config".to_string()));
        assert!(!args.iter().any(|arg| arg.contains("bypass")));
        assert!(CLAUDE_SETTINGS.contains("\"disableAllHooks\": true"));
    }

    #[test]
    fn test_codex_runs_read_only_without_shell() {
        let args: Vec<String> = agent_args(
            AgentKind::Codex,
            "",
            Path::new("settings.json"),
            Some(Path::new("answer.txt")),
        )
        .into_iter()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect();
        assert_eq!(args[0], "exec");
        let joined = args.join(" ");
        assert!(joined.contains("--sandbox read-only"));
        assert!(joined.contains("-c features.shell_tool=false"));
        assert!(joined.contains("--output-last-message answer.txt"));
        assert!(!joined.contains("--model"));
        assert!(!joined.contains("full-auto") && !joined.contains("danger"));
        assert_eq!(args.last().map(String::as_str), Some("-"));
    }

    #[test]
    fn test_choose_agent() {
        let only = |installed: AgentKind| {
            move |kind: AgentKind| (kind == installed).then(|| PathBuf::from("agent"))
        };
        // Without Claude Code, "auto" picks Codex.
        let agent = choose_agent(AiCommandAgent::Auto, only(AgentKind::Codex)).unwrap();
        assert_eq!(agent.kind, AgentKind::Codex);
        // Both installed: Claude Code first.
        let agent = choose_agent(AiCommandAgent::Auto, |_| Some(PathBuf::from("x"))).unwrap();
        assert_eq!(agent.kind, AgentKind::ClaudeCode);
        // Asking for one that isn't installed fails, saying how to install it.
        let error = choose_agent(AiCommandAgent::ClaudeCode, only(AgentKind::Codex)).unwrap_err();
        assert!(
            error.to_string().contains("install.ps1") || error.to_string().contains("install.sh")
        );
        let error = choose_agent(AiCommandAgent::Auto, |_| None).unwrap_err();
        assert!(error.to_string().contains("npm install -g @openai/codex"));
    }

    /// A stand-in for Claude Code that answers with a command deleting
    /// everything. Generating must only return the command, not run it.
    #[cfg(windows)]
    #[test]
    fn test_generating_runs_nothing() {
        let bin = tempfile::tempdir().unwrap();
        let project = tempfile::tempdir().unwrap();
        let precious = project.path().join("precious.txt");
        std::fs::write(&precious, "keep me").unwrap();
        let fake = bin.path().join("claude.cmd");
        std::fs::write(
            &fake,
            "@echo off\r\n\
             echo %* > \"%~dp0args.txt\"\r\n\
             more > \"%~dp0prompt.txt\"\r\n\
             echo Remove-Item -Recurse -Force *\r\n",
        )
        .unwrap();
        let agent = Agent {
            kind: AgentKind::ClaudeCode,
            program: fake,
        };
        let command = generate_with(
            &agent,
            &Request {
                request: "delete the files in this directory".into(),
                shell: Some("powershell".into()),
                cwd: Some(project.path().to_path_buf()),
                context: Vec::new(),
            },
            &Options {
                claude_model: "haiku".into(),
                ..Default::default()
            },
            &AtomicBool::new(false),
        )
        .unwrap();
        assert_eq!(command, "Remove-Item -Recurse -Force *");
        assert!(precious.is_file(), "generating must not run the command");
        let args = std::fs::read_to_string(bin.path().join("args.txt")).unwrap();
        assert!(args.contains("--tools \"\""), "{args}");
        assert!(args.contains("--disallowedTools *"), "{args}");
        let prompt = std::fs::read_to_string(bin.path().join("prompt.txt")).unwrap();
        assert!(prompt.contains("Request: delete the files in this directory"));
        assert!(prompt.contains(&project.path().display().to_string()));
    }

    #[cfg(windows)]
    #[test]
    fn test_cancel_stops_the_agent() {
        let bin = tempfile::tempdir().unwrap();
        let fake = bin.path().join("codex.cmd");
        std::fs::write(
            &fake,
            "@echo off\r\nping -n 30 127.0.0.1 > nul\r\necho ls\r\n",
        )
        .unwrap();
        let cancel = std::sync::Arc::new(AtomicBool::new(false));
        let started = Instant::now();
        let thread = std::thread::spawn({
            let cancel = cancel.clone();
            move || {
                generate_with(
                    &Agent {
                        kind: AgentKind::Codex,
                        program: fake,
                    },
                    &Request::default(),
                    &Options::default(),
                    &cancel,
                )
            }
        });
        std::thread::sleep(Duration::from_millis(300));
        cancel.store(true, Ordering::Relaxed);
        let error = thread.join().unwrap().unwrap_err();
        assert!(error.is::<Cancelled>());
        assert!(started.elapsed() < Duration::from_secs(10));
    }
}
